      zh: {
        name: "\u5DF4\u7279\u7F57\u4E4B\u5BB6",
        narration: "\u6B22\u8FCE\u6765\u5230\u5DF4\u7279\u7F57\u4E4B\u5BB6,\u9AD8\u8FEA\u6700\u5BCC\u60F3\u8C61\u529B\u7684\u5EFA\u7B51\u4E4B\u4E00\u3002\u8FD9\u5EA7\u4EE4\u4EBA\u60CA\u53F9\u7684\u73B0\u4EE3\u4E3B\u4E49\u6770\u4F5C\u4EE5\u5176\u9AA8\u9ABC\u822C\u7684\u7ACB\u9762\u548C\u9F99\u5F62\u5C4B\u9876\u7C7B\u4F3C\u4E8E\u4E00\u4E2A\u6D3B\u7684\u6709\u673A\u4F53\u3002",
        description: "\u9AD8\u8FEA\u5E7B\u60F3\u7684\u73B0\u4EE3\u4E3B\u4E49\u5EFA\u7B51,\u62E5\u6709\u9AA8\u9ABC\u7ACB\u9762",
        detailedDescription: "\u5DF4\u7279\u7F57\u4E4B\u5BB6\u662F\u4F4D\u4E8E\u5DF4\u585E\u7F57\u90A3\u5E02\u4E2D\u5FC3\u7684\u4E00\u5EA7\u5EFA\u7B51,\u7531\u5B89\u4E1C\u5C3C\xB7\u9AD8\u8FEA\u4E8E1904\u5E74\u81F31906\u5E74\u8FDB\u884C\u7FFB\u65B0\u3002\u5B83\u4F4D\u4E8E\u683C\u62C9\u897F\u4E9A\u5927\u9053\u4E0A,\u662F\u9AD8\u8FEA\u7684\u6770\u4F5C\u4E4B\u4E00\u3002\u8BE5\u5EFA\u7B51\u662F\u8054\u5408\u56FD\u6559\u79D1\u6587\u7EC4\u7EC7\u4E16\u754C\u9057\u4EA7\u7684\u4E00\u90E8\u5206\u3002\u8BE5\u5EFA\u7B51\u7684\u5F53\u5730\u540D\u79F0\u662F\u9AA8\u5934\u4E4B\u5BB6(Casa dels ossos),\u56E0\u4E3A\u5B83\u5177\u6709\u5185\u810F\u7684\u3001\u9AA8\u9ABC\u7684\u6709\u673A\u7279\u8D28\u3002\u7ACB\u9762\u88C5\u9970\u7740\u5F69\u8272\u9A6C\u8D5B\u514B,\u9633\u53F0\u7C7B\u4F3C\u4E8E\u5934\u9AA8\u6216\u9762\u5177\u3002\u5C4B\u9876\u5448\u62F1\u5F62,\u7C7B\u4F3C\u4E8E\u9F99\u7684\u80CC\u90E8,\u5C4B\u74E6\u770B\u8D77\u6765\u50CF\u9CDE\u7247\u3002\u5728\u5185\u90E8,\u9AD8\u8FEA\u7684\u6709\u673A\u8BBE\u8BA1\u7EE7\u7EED\u7740,\u6709\u5F2F\u66F2\u7684\u5899\u58C1\u3001\u8611\u83C7\u5F62\u58C1\u7089\u548C\u4E00\u4E2A\u58EE\u89C2\u7684\u5929\u4E95,\u65E8\u5728\u5C06\u81EA\u7136\u5149\u5206\u5E03\u5230\u6574\u4E2A\u5EFA\u7B51\u3002",
        historicalInfo: "\u5DF4\u7279\u7F57\u4E4B\u5BB6\u6700\u521D\u7531\u9AD8\u8FEA\u7684\u5EFA\u7B51\u8001\u5E08\u4E4B\u4E00\u57C3\u7C73\u5229\xB7\u8428\u62C9\xB7\u79D1\u5C14\u7279\u65AF\u4E8E1877\u5E74\u5EFA\u9020\u30021904\u5E74,\u7EA6\u745F\u666E\xB7\u5DF4\u7279\u7F57\u59D4\u6258\u9AD8\u8FEA\u7FFB\u65B0\u8FD9\u5EA7\u5EFA\u7B51\u3002\u9AD8\u8FEA\u57281904\u5E74\u81F31906\u5E74\u95F4\u5F7B\u5E95\u6539\u9020\u4E86\u8FD9\u5EA7\u5EFA\u7B51\u30022005\u5E74,\u5DF4\u7279\u7F57\u4E4B\u5BB6\u4E0E\u9AD8\u8FEA\u7684\u5176\u4ED6\u4F5C\u54C1\u4E00\u8D77\u88AB\u6307\u5B9A\u4E3A\u8054\u5408\u56FD\u6559\u79D1\u6587\u7EC4\u7EC7\u4E16\u754C\u9057\u4EA7\u3002",
        yearBuilt: "1877\u5E74 (\u539F\u5EFA\u7B51), 1904-1906\u5E74 (\u9AD8\u8FEA\u7FFB\u65B0)",
        architect: "\u5B89\u4E1C\u5C3C\xB7\u9AD8\u8FEA (\u7FFB\u65B0)"
      }
