    console.log(`\u2705 \uD30C\uD2B8\uB108 \uC9C0\uAC11\uC5D0 ${partnerReward}\uC6D0\uC774 \uC131\uACF5\uC801\uC73C\uB85C \uC801\uB9BD\uB418\uC5C8\uC2B5\uB2C8\uB2E4.`);
